    quintal: {
        id: 'quintal',
        nome: 'Quintal / Jardim', nome_ptpt: 'Quintal / Jardim', nome_es: 'Patio / Jardín', nome_en: 'Backyard / Garden',
        emoji: '🌳',
        cor: '#43A047',
        capa: [
            require('../assets/illustrations/pad/ambientes-casa_jardim_019.jpg'),
              require('../assets/illustrations/pad/ambientes-casa_jardim_019.jpg'),
        ],
        conteudo: [
            { tipo: 'destaque', texto: 'O quintal é onde a criança tem mais liberdade para brincar, e exatamente por isso merece um mapeamento cuidadoso dos riscos.', texto_ptpt: 'O quintal é onde a criança tem mais liberdade para brincar, e é exatamente por isso que merece um mapeamento cuidadoso dos riscos.', texto_es: 'El patio es donde el niño tiene más libertad para jugar, y precisamente por eso merece un mapeo cuidadoso de los riesgos.', texto_en: 'The backyard is where children have the most freedom to play, and that is exactly why its risks deserve careful mapping.' },
            { tipo: 'topico', titulo: 'Plantas Tóxicas e Animais Peçonhentos', titulo_ptpt: 'Plantas Tóxicas e Animais Peçonhentos', titulo_es: 'Plantas Tóxicas y Animales Venenosos', titulo_en: 'Toxic Plants and Venomous Animals', texto: 'As regras sobre plantas venenosas (comigo-ninguém-pode, espirradeira) e o combate a escorpiões e aranhas estão centralizadas. Consulte os Guias "Plantas Tóxicas" e "Animais Peçonhentos" na seção de Riscos.', texto_ptpt: 'As regras sobre plantas venenosas (diefembáquia, loendro) e o combate a escorpiões e aranhas estão centralizadas. Consulte os guias «Plantas Tóxicas» e «Animais Peçonhentos» na secção de Riscos.', texto_es: 'Las reglas sobre plantas venenosas (difenbaquia, adelfa) y el control de escorpiones y arañas están centralizadas. Consulte las guías «Plantas Tóxicas» y «Animales Venenosos» en la sección de Riesgos.', texto_en: 'The rules on poisonous plants (dumb cane, oleander) and on controlling scorpions and spiders have been brought together. See the "Toxic Plants" and "Venomous Animals" guides in the Risks section.' },
            { tipo: 'topico', titulo: 'Ferramentas e Produtos Químicos', titulo_ptpt: 'Ferramentas e Produtos Químicos', titulo_es: 'Herramientas y Productos Químicos', titulo_en: 'Tools and Chemical Products', texto: 'Todas as ferramentas e produtos tóxicos devem seguir os protocolos rigorosos descritos no Guia de EPIs e Ferramentas.', texto_ptpt: 'Todas as ferramentas e produtos tóxicos devem seguir os protocolos rigorosos descritos no Guia de EPI e Ferramentas.', texto_es: 'Todas las herramientas y productos tóxicos deben seguir los protocolos estrictos descritos en la Guía de EPI y Herramientas.', texto_en: 'All tools and toxic products must follow the strict protocols described in the PPE and Tools Guide.' }
        ]
    },

    jardinagem: {
        id: 'jardinagem',
        nome: 'Jardinagem / Plantas', nome_ptpt: 'Jardinagem / Plantas', nome_es: 'Jardinería / Plantas', nome_en: 'Gardening / Plants',
        emoji: '🌱',
        cor: '#8BC34A',
        capa: [
              require('../assets/illustrations/pad/ambientes-casa_jardim_019.jpg'),
              require('../assets/illustrations/pad/generated_jardim.png'),
          ],
        conteudo: [
              { tipo: 'destaque', texto: 'Cuidar do jardim ou da horta traz riscos próprios, que vão da insolação à intoxicação potencialmente letal por produtos químicos.', texto_ptpt: 'Cuidar do jardim ou da horta traz riscos próprios, que vão da insolação à intoxicação potencialmente letal por produtos químicos.', texto_es: 'Cuidar del jardín o del huerto tiene riesgos propios, que van de la insolación a la intoxicación potencialmente mortal por productos químicos.', texto_en: 'Looking after a garden or vegetable plot has its own risks, from sunstroke to potentially fatal poisoning by chemical products.' },
              { tipo: 'topico', titulo: 'Fertilizantes e Pesticidas', titulo_ptpt: 'Adubos e Pesticidas', titulo_es: 'Abonos y Pesticidas', titulo_en: 'Fertilisers and Pesticides', texto: 'O uso e o armazenamento inadequado de produtos químicos de jardinagem representam alto risco de intoxicação letal para crianças e pets. Mantenha trancados em armários altos ou caixas originais rotuladas. Dê preferência aos naturais.', texto_ptpt: 'O uso e o armazenamento inadequados de produtos químicos de jardinagem representam um alto risco de intoxicação letal para crianças e animais. Mantenha-os fechados à chave em armários altos ou nas caixas originais rotuladas. Dê preferência aos naturais.', texto_es: 'El uso y almacenamiento inadecuados de productos químicos de jardinería suponen un alto riesgo de intoxicación mortal para niños y mascotas. Guárdelos bajo llave en armarios altos o en sus cajas originales etiquetadas. Prefiera los naturales.', texto_en: 'Improper use and storage of garden chemicals carries a high risk of fatal poisoning for children and pets. Keep them locked in high cupboards or in their original labelled boxes. Prefer natural products.' },
              { tipo: 'topico', titulo: 'Exposição ao Clima e Insolação', titulo_ptpt: 'Exposição ao Clima e Insolação', titulo_es: 'Exposición al Clima e Insolación', titulo_en: 'Weather Exposure and Sunstroke', texto: 'Ficar exposto ao sol quente por longos períodos pode causar mal-estar severo. Utilize chapéus, protetor solar e priorize o trabalho nas primeiras horas da manhã ou no fim da tarde.', texto_ptpt: 'Ficar exposto ao sol quente durante muito tempo pode causar mal-estar grave. Use chapéu e protetor solar e trabalhe de preferência logo de manhã ou ao fim da tarde.', texto_es: 'Estar expuesto al sol fuerte durante mucho tiempo puede causar un malestar grave. Use sombrero y protector solar y trabaje a primera hora de la mañana o al final de la tarde.', texto_en: 'Long periods in hot sun can make you seriously unwell. Wear a hat and sunscreen and work early in the morning or late in the afternoon.' },
              { tipo: 'topico', titulo: 'A "Armadura" do Jardineiro', titulo_ptpt: 'A «Armadura» do Jardineiro', titulo_es: 'La «Armadura» del Jardinero', titulo_en: 'The Gardener’s "Armour"', texto: 'Use sempre luvas, calçados fechados (ou botas), além de camisas de manga comprida e calças com as barras fechadas, para dificultar que insetos subam e que plantas nocivas queimem a pele.', texto_ptpt: 'Use sempre luvas, calçado fechado (ou botas), camisas de manga comprida e calças com as bainhas fechadas, para dificultar que os insetos subam e que plantas nocivas queimem a pele.', texto_es: 'Use siempre guantes, calzado cerrado (o botas), camisas de manga larga y pantalones con los bajos cerrados, para dificultar que suban insectos y que las plantas dañinas quemen la piel.', texto_en: 'Gloves, closed shoes (or boots), long-sleeved shirts and trousers with closed hems are a must to help stop insects climbing up and harmful plants burning the skin.' },
              { tipo: 'dica', texto: 'Identifique e evite cultivar plantas tóxicas em áreas de fácil acesso a crianças e pets. Ao podá-las, use luvas, pois muitas liberam seiva corrosiva.', texto_ptpt: 'Identifique e evite cultivar plantas tóxicas em zonas de fácil acesso a crianças e animais. Ao podá-las, use luvas, pois muitas libertam seiva corrosiva.', texto_es: 'Identifique las plantas tóxicas y evite cultivarlas en zonas de fácil acceso para niños y mascotas. Al podarlas, use guantes, porque muchas liberan savia corrosiva.', texto_en: 'Identify toxic plants and avoid growing them where children and pets can easily reach them. Wear gloves when pruning, as many release corrosive sap.' }
          ]
    },

